"""Find the out-of-line standard-container operations on ROS message types in a set of shared libraries — the
probe/interposition points for node-internal message flow (deposit into a member container, consumption/clear).
  python3 scan_container_symbols.py <libdir> [<libdir> ...] [--json out.json]
Why these symbols: push_back/clear are inlined, but libstdc++ keeps the slow paths out of line and exported (weak):
  deque<T>::_M_push_back_aux / _M_push_front_aux   (every push when sizeof(T) > 256: libstdc++ chunk = 512/sizeof(T) = 1 element)
  deque<T>::_M_erase_at_end / _M_erase_at_begin    (clear(), pop)
  vector<T>::_M_realloc_insert                      (growth only: not per element)
  _Rb_tree<K,...,pair<K,T>...>::_M_emplace_unique / _M_insert_unique / _M_emplace_hint_unique   (std::map insert)
  _Hashtable<...>::_M_emplace / _M_insert_unique_node                                            (unordered_map)
Element type filter: a ROS message (`::msg::`) or a shared_ptr to one (then the pushed value IS the message pointer)."""
import argparse, json, os, re, subprocess, sys
ap = argparse.ArgumentParser(); ap.add_argument('libdirs', nargs='+'); ap.add_argument('--json', default=None)
a = ap.parse_args()
PAT = re.compile(r'(_M_push_back_aux|_M_push_front_aux|_M_erase_at_end|_M_erase_at_begin|_M_realloc_insert|_M_emplace_unique|_M_insert_unique|_M_emplace_hint_unique|_M_emplace|_M_insert_unique_node)')
rows = []
for d in a.libdirs:
    for root, _, files in os.walk(d):
        for fn in sorted(files):
            if not fn.endswith('.so') and '.so.' not in fn: continue
            p = os.path.join(root, fn)
            try:
                out = subprocess.run(['nm', '-D', '--defined-only', p], capture_output=True, text=True).stdout
            except Exception:
                continue
            mangled = [l.split()[2] for l in out.splitlines() if len(l.split()) == 3 and (' W ' in l or ' T ' in l) and ('deque' in l or '_Rb_tree' in l or '_Hashtable' in l or 'vector' in l) and PAT.search(l)]
            if not mangled: continue
            dem = subprocess.run(['c++filt'] + mangled, capture_output=True, text=True).stdout.splitlines()
            for m, dm in zip(mangled, dem):
                if '::msg::' not in dm: continue
                kind = PAT.search(dm).group(1)
                cont = 'deque' if 'std::deque<' in dm else 'vector' if 'std::vector<' in dm else 'map' if '_Rb_tree' in dm else 'umap' if '_Hashtable' in dm else '?'
                sp = 'std::shared_ptr<' in dm.split('::_M_')[0]
                et = re.search(r'(?:deque|vector)<(.*?), std::allocator', dm)
                rows.append(dict(lib=p, symbol=m, kind=kind, container=cont, elem_shared_ptr=sp, elem=(et.group(1) if et else dm.split('::_M_')[0])[:120]))
print(f'{len(rows)} container operations on ROS message types in {len({r["lib"] for r in rows})} libraries')
import collections
print('by container/kind:', dict(collections.Counter((r['container'], r['kind']) for r in rows)))
print('per element (per-push guaranteed only for deque with sizeof(T) > 256 or shared_ptr elements via map/umap):')
for r in rows[:40]:
    print(f"  {os.path.basename(r['lib']):55s} {r['container']:6s} {r['kind']:22s} {'shared_ptr' if r['elem_shared_ptr'] else 'value':10s} {r['elem'][:60]}")
if len(rows) > 40: print(f'  ... {len(rows) - 40} more')
if a.json: json.dump(rows, open(a.json, 'w'), indent=1); print('wrote', a.json)
